#!/bin/bash
cidr="$2"; mask=$((0xFFFFFFFF << (32 - cidr) & 0xFFFFFFFF)); IFS=. read -r i1 i2 i3 i4 <<< "$1"; ip=$((i1 << 24 | i2 << 16 | i3 << 8 | i4)); network=$((ip & mask)); broadcast=$((network | (~mask & 0xFFFFFFFF))); first=$((network + 1)); last=$((broadcast - 1)); printf "%d.%d.%d.%d - %d.%d.%d.%d\n" "$((first >> 24 & 255))" "$((first >> 16 & 255))" "$((first >> 8 & 255))" "$((first & 255))" "$((last >> 24 & 255))" "$((last >> 16 & 255))" "$((last >> 8 & 255))" "$((last & 255))"